import { useSignIn } from "@clerk/expo/legacy";
import { Ionicons } from "@expo/vector-icons";
import { useRouter } from "expo-router";
import { useState } from "react";
import {
  ActivityIndicator,
  ScrollView,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";

import BrandLoader from "@/components/BrandLoader";
import { showMessage } from "@/lib/alerts";
import { authStyles } from "@/lib/authStyles";
import { getClerkErrorMessage } from "@/lib/clerkErrors";
import palette from "@/lib/theme";

// Typed routes are regenerated by Expo during development; the exported route is /sign-up.
const SIGN_UP_HREF = "/sign-up" as Parameters<ReturnType<typeof useRouter>["push"]>[0];

const SignInScreen = () => {
  const router = useRouter();
  const { isLoaded, signIn, setActive } = useSignIn();
  const [emailAddress, setEmailAddress] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);

  if (!isLoaded) return <BrandLoader label="Preparing sign-in…" />;

  const handleSignIn = async () => {
    const email = emailAddress.trim().toLowerCase();

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      showMessage("Check your email", "Enter the email address you registered with.");
      return;
    }
    if (!password) {
      showMessage("Check your password", "Enter your password to continue.");
      return;
    }

    setLoading(true);
    try {
      const result = await signIn.create({ identifier: email, password });

      if (!result.createdSessionId) {
        showMessage(
          "Additional verification needed",
          "Finish the verification step shown below, or use the sign-in method you chose when you registered."
        );
        return;
      }

      await setActive({ session: result.createdSessionId });
      router.replace("/(tabs)");
    } catch (error) {
      showMessage(
        "Unable to sign in",
        getClerkErrorMessage(error, "Check your email and password and try again.")
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <ScrollView
      className="flex-1"
      style={{ flex: 1, backgroundColor: palette.light.background }}
      contentContainerStyle={{
        flexGrow: 1,
        alignItems: "center",
        justifyContent: "center",
        paddingHorizontal: 24,
        paddingVertical: 32,
      }}
      keyboardShouldPersistTaps="handled"
    >
      <View style={{ width: "100%", maxWidth: 360, gap: 16 }}>
        <View style={{ alignItems: "center", marginBottom: 8 }}>
          <View
            style={{
              width: 64,
              height: 64,
              borderRadius: 32,
              alignItems: "center",
              justifyContent: "center",
              backgroundColor: `${palette.brand.DEFAULT}20`,
            }}
          >
            <Ionicons name="log-in-outline" size={30} color={palette.brand.DEFAULT} />
          </View>
          <Text style={{ marginTop: 16, fontSize: 28, fontWeight: "700", color: palette.brand.DEFAULT }}>
            Welcome back
          </Text>
          <Text
            style={{
              marginTop: 4,
              textAlign: "center",
              color: palette.light.muted,
              fontSize: 14,
              lineHeight: 20,
            }}
          >
            Sign in with the email address and password you used to register.
          </Text>
        </View>

        <TextInput
          value={emailAddress}
          onChangeText={setEmailAddress}
          placeholder="Email address"
          placeholderTextColor={palette.light.muted}
          keyboardType="email-address"
          autoCapitalize="none"
          autoComplete="email"
          textContentType="emailAddress"
          editable={!loading}
          style={authStyles.input}
          accessibilityLabel="Email address"
        />
        <TextInput
          value={password}
          onChangeText={setPassword}
          placeholder="Password"
          placeholderTextColor={palette.light.muted}
          secureTextEntry
          autoCapitalize="none"
          autoComplete="current-password"
          textContentType="password"
          returnKeyType="go"
          onSubmitEditing={handleSignIn}
          editable={!loading}
          style={authStyles.input}
          accessibilityLabel="Password"
        />

        <TouchableOpacity
          onPress={handleSignIn}
          disabled={loading}
          style={[authStyles.primaryButton, { opacity: loading ? 0.7 : 1 }]}
          accessibilityRole="button"
          accessibilityLabel="Sign in"
          accessibilityState={{ disabled: loading, busy: loading }}
        >
          {loading ? (
            <ActivityIndicator color="#ffffff" />
          ) : (
            <Text style={authStyles.primaryButtonLabel}>Sign in</Text>
          )}
        </TouchableOpacity>

        <TouchableOpacity
          onPress={() => router.push(SIGN_UP_HREF)}
          disabled={loading}
          style={{ marginTop: 8, alignItems: "center" }}
          accessibilityRole="link"
          accessibilityLabel="Create an account"
        >
          <Text style={{ color: palette.light.muted, fontSize: 14 }}>
            New to AfriCart?{" "}
            <Text style={{ color: palette.light.link, fontWeight: "600" }}>Create account</Text>
          </Text>
        </TouchableOpacity>
      </View>
    </ScrollView>
  );
};

export default SignInScreen;
